#!/usr/bin/env bash
# HyperShots renderer: headless Chrome at an exact per-profile canvas.
set -euo pipefail

WS="${1:?usage: render.sh <workspace> [profile] [locale] [--grid]}"
PROFILE="${2:-iphone-6.9}"
LOCALE="${3:-en}"
GRID=0
if [ "${4:-}" = "--grid" ]; then GRID=1
elif [ -n "${4:-}" ]; then echo "ERROR: unknown arg '${4}' (only --grid is accepted)" >&2; exit 1; fi
KIT="$(cd "$(dirname "$0")/.." && pwd)"     # skills/hypershots

find_chrome() {
  if [ -n "${CHROME:-}" ]; then echo "$CHROME"; return; fi
  local mac="/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"
  [ -x "$mac" ] && { echo "$mac"; return; }
  for c in google-chrome chromium chromium-browser; do
    command -v "$c" >/dev/null 2>&1 && { command -v "$c"; return; }
  done
  echo "ERROR: no Chrome/Chromium found. Set \$CHROME." >&2; exit 1
}
CHROME_BIN="$(find_chrome)"

# Keep headless Chrome isolated from the user's running browser profile. A bounded watchdog
# makes a renderer regression fail the panel instead of wedging the whole factory run.
CHROME_TIMEOUT="${HYPERSHOTS_CHROME_TIMEOUT:-45}"
[[ "$CHROME_TIMEOUT" =~ ^[1-9][0-9]*$ ]] || {
  echo "ERROR: HYPERSHOTS_CHROME_TIMEOUT must be a positive integer" >&2
  exit 2
}
CHROME_PROFILE="$(mktemp -d "${TMPDIR:-/tmp}/hypershots-chrome.XXXXXX")"
cleanup_chrome_profile() { rm -rf -- "$CHROME_PROFILE"; }
trap cleanup_chrome_profile EXIT

# Chrome 150 on macOS can finish --screenshot/--dump-dom successfully but keep its
# headless browser process alive. Treat a complete artifact as success, then terminate
# only the isolated process group created for that invocation. A missing artifact still
# fails at the same bounded timeout.
stop_chrome_group() {
  local pid="$1"
  kill -TERM -- "-$pid" 2>/dev/null || true
  wait "$pid" 2>/dev/null || true
}

artifact_ready() {
  local artifact="$1" kind="$2"
  [ -s "$artifact" ] || return 1
  if [ "$kind" = "dom" ]; then
    grep -q 'id="hypershots-boxes"' "$artifact" && grep -q '</html>' "$artifact"
  fi
}

run_chrome_until_artifact() {
  local artifact="$1" kind="$2" log="$3"
  shift 3
  local stdout_target="${artifact}.stdout"
  [ "$kind" = "dom" ] && stdout_target="$artifact"

  # setpgrp keeps cleanup scoped to this headless invocation and its helpers.
  perl -e 'setpgrp(0,0); exec @ARGV' -- "$CHROME_BIN" "$@" >"$stdout_target" 2>"$log" &
  local pid=$! deadline=$((SECONDS + CHROME_TIMEOUT)) rc=0 size_before size_after

  while kill -0 "$pid" 2>/dev/null; do
    if artifact_ready "$artifact" "$kind"; then
      # Avoid accepting a PNG while Chrome is still flushing it.
      if [ "$kind" = "png" ]; then
        size_before="$(stat -f '%z' "$artifact")"
        sleep 0.2
        size_after="$(stat -f '%z' "$artifact")"
        [ "$size_before" = "$size_after" ] || continue
      fi
      stop_chrome_group "$pid"
      [ "$stdout_target" = "$artifact" ] || rm -f "$stdout_target"
      return 0
    fi
    if [ "$SECONDS" -ge "$deadline" ]; then
      stop_chrome_group "$pid"
      [ "$stdout_target" = "$artifact" ] || rm -f "$stdout_target"
      echo "ERROR: Chrome timed out before producing complete $kind output: $artifact" >&2
      return 142
    fi
    sleep 0.1
  done

  wait "$pid" || rc=$?
  [ "$stdout_target" = "$artifact" ] || rm -f "$stdout_target"
  if [ "$rc" -eq 0 ] && artifact_ready "$artifact" "$kind"; then return 0; fi
  echo "ERROR: Chrome exited before producing complete $kind output: $artifact" >&2
  [ "$rc" -ne 0 ] && return "$rc"
  return 1
}

# profile -> css dims + scale. Plain assignment (not read <<< "$(...)") so an
# unknown profile trips set -e HERE, before profile.css is written.
DIMS="$(node "$KIT/scripts/lib/profile-dims.mjs" "$KIT/profiles.json" "$PROFILE")"
read -r W H SCALE OW OH <<< "$DIMS"
[ -n "$OH" ] || { echo "ERROR: bad dims line for profile $PROFILE" >&2; exit 1; }

# per-profile variable injection (the mechanism that prevents gutters).
# --grid adds --hs-grid:1: fit.js draws a labeled 50px coordinate grid overlay.
GRID_VAR=""; [ "$GRID" -eq 1 ] && GRID_VAR=" --hs-grid:1;"
cat > "$WS/profile.css" <<EOF
/* generated by render.sh — do not edit */
:root{ --panel-w:${W}px; --panel-h:${H}px;${GRID_VAR} }
EOF

SRC="$WS/panels"; [ "$LOCALE" != "en" ] && SRC="$WS/panels-$LOCALE"
# grid renders are quarantined in <locale>-grid so validate.sh never sees them
OUT="$WS/out/$PROFILE/$LOCALE"; [ "$GRID" -eq 1 ] && OUT="$WS/out/$PROFILE/$LOCALE-grid"
mkdir -p "$OUT"
# no stale outputs: a removed/renamed panel must not leave last run's files
rm -f "$OUT"/panel-*.png "$OUT"/panel-*.boxes.json

FLAGS=(--headless=new --disable-gpu --hide-scrollbars --no-sandbox
  --user-data-dir="$CHROME_PROFILE" --no-first-run --no-default-browser-check
  --disable-background-networking
  --force-device-scale-factor="$SCALE" --window-size="$W,$H"
  --default-background-color=FFFFFFFF --force-color-profile=srgb
  --virtual-time-budget=8000)

shopt -s nullglob
PANELS=("$SRC"/panel-*.html)
[ ${#PANELS[@]} -gt 0 ] || { echo "ERROR: no panels in $SRC" >&2; exit 1; }

for f in "${PANELS[@]}"; do
  n="$(basename "$f" .html)"
  # Chrome needs an absolute file:// URL; $WS may be a relative path
  f="$(cd "$(dirname "$f")" && pwd)/$(basename "$f")"
  LOG="$OUT/$n.chrome.log"; TMP="$OUT/$n.boxes.json.tmp"; DOM="$OUT/$n.dom.tmp"
  # pass 1: screenshot (no || true — a Chrome crash/hang must fail the build)
  run_chrome_until_artifact "$OUT/$n.png" png "$LOG" \
    "${FLAGS[@]}" --screenshot="$OUT/$n.png" "file://$f"
  # pass 2: dump DOM -> boxes + fit failures (fit.js is deterministic across
  # passes). boxes.json is committed only on success, and a failed panel must
  # not leave its PNG behind for validate.sh to bless.
  rc=0
  run_chrome_until_artifact "$DOM" dom "$LOG" "${FLAGS[@]}" --dump-dom "file://$f"
  node -e '
      const [expW, expH] = [process.argv[1], process.argv[2]].map(Number);
      let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{
        const m=s.match(/<script[^>]*\bid="hypershots-boxes"[^>]*>(.*?)<\/script>/s);
        if(!m){console.error("ERROR: no boxes dump — is fit.js included last in the panel?");process.exit(1)}
        const j=JSON.parse(m[1]);
        if(j.panelW!==expW||j.panelH!==expH){console.error(`ERROR: panel is ${j.panelW}x${j.panelH} but profile expects ${expW}x${expH} — is profile.css linked?`);process.exit(3)}
        if(j.fitFailures.length){console.error("FIT FAILURE (copy needs a rewrite): "+j.fitFailures.join(", "));process.exit(2)}
        // warnings, never failures: taste calls belong to the review loop
        const small=(j.copy||[]).filter(c=>c.px<15);
        if(small.length)console.error("LEGIBILITY WARNING: copy under 15px reads as noise at store-thumbnail scale — "+small.map(c=>c.name+" "+c.px+"px").join(", ")+" (reword or restyle, see create.md copy contract)");
        if((j.mockups||[]).length)console.error("MOCKUP UI: hand-built screen content ["+j.mockups.map(m=>m.name).join(", ")+"] — replace with real captures before submission (App Review 2.3.3)");
        console.log(JSON.stringify(j,null,1));})' "$W" "$H" < "$DOM" > "$TMP" || rc=$?
  if [ "$rc" -ne 0 ]; then
    rm -f "$OUT/$n.png" "$TMP" "$DOM" # no orphan PNG, no partial boxes.json
    exit "$rc"                      # $LOG is kept for debugging
  fi
  mv "$TMP" "$OUT/$n.boxes.json"
  rm -f "$LOG" "$DOM"
  echo "rendered $n -> $OUT/$n.png (target ${OW}x${OH})"
done
if [ "$GRID" -eq 1 ]; then
  echo "OK: ${#PANELS[@]} panels rendered for $PROFILE/$LOCALE-grid"
  echo "*** GRID RENDER — not for upload. Debug overlay only; outputs quarantined in $OUT ***"
else
  echo "OK: ${#PANELS[@]} panels rendered for $PROFILE/$LOCALE"
fi
